import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson 2021-02-23","description":"","frontmatter":{"title":"Ceph Crimson 2021-02-23","date":"2021-02-23T00:00:00.000Z","updated":"2021-02-26T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_2021-02-23.md","filePath":"posts/2021/Ceph_Crimson_2021-02-23.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Crimson_2021-02-23.md"};function o(s,l,n,h,p,u){return e(),a("div",null,[...l[0]||(l[0]=[t('<p>会议纪要</p><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>参会人员</strong>: Sherhan及其他团队成员。</li><li><strong>时间</strong>: 近期一周。</li><li><strong>主要议题</strong>: 讨论了客户端请求序列器的优化、单元测试的添加、3D课堂项目构建问题、以及Ceph存储系统中的并发优化。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>客户端请求序列器优化</strong>:</p><ul><li>Sherhan和团队正在优化客户端请求序列器，并尝试添加单元测试。</li><li>讨论了不同构建环境下的性能差异，特别是发布构建和调试构建的性能表现。</li></ul></li><li><p><strong>3D课堂项目</strong>:</p><ul><li>项目在调试构建中运行正常，但在发布构建中崩溃。</li><li>讨论了硬件性能对构建的影响，特别是SSD和NVMe硬盘的读取速度问题。</li></ul></li><li><p><strong>Ceph存储系统并发优化</strong>:</p><ul><li>讨论了如何在Ceph存储系统中优化并发处理，特别是在crimson osd中的并发请求管道。</li><li>强调了客户端请求在底层磁盘上的持久化顺序的重要性，以及如何在Ceph的不同存储实现中保证这一顺序。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><p><strong>发布构建崩溃问题</strong>:</p><ul><li>决定暂时不深入调试，因为代码频繁变动。</li><li>建议通过添加更多断言或日志输出帮助定位问题。</li></ul></li><li><p><strong>并发优化</strong>:</p><ul><li>确认了在Ceph存储系统中，客户端请求的持久化顺序必须与它们到达OSD的顺序一致。</li><li>讨论了在alien store中如何保证这一顺序，建议通过哈希集合到线程集合的方式来保证顺序。</li></ul></li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><p><strong>发布构建崩溃问题</strong>:</p><ul><li>继续监控和收集更多日志信息，以便更好地理解崩溃原因。</li><li>在代码稳定后，重新考虑深入调试。</li></ul></li><li><p><strong>并发优化</strong>:</p><ul><li>在alien store中实施保证客户端请求顺序的机制。</li><li>探索Ceph中是否已有类似的并发处理工具或库，以便更高效地实现并发优化。</li></ul></li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了硬件性能对软件构建的影响，特别是SSD和NVMe硬盘的读取速度问题。</li><li>确认了在Ceph存储系统中，多个PG的使用是为了实现并行处理，而不是在单个PG内实现并行。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议强调了在Ceph存储系统中保证客户端请求顺序的重要性，并讨论了如何在不同构建环境和硬件条件下优化性能。后续行动计划包括继续监控和调试发布构建的崩溃问题，以及在alien store中实施并发优化措施。</p>',13)])])}const c=i(r,[["render",o]]);export{_ as __pageData,c as default};
